func TestAddDeduplicates(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "known-modules")
	for i := 0; i < 3; i++ {
		if err := Add(path, "iac/comply/aws"); err != nil {
			t.Fatalf("Add iteration %d: %v", i, err)
		}
	}
	body, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	lines := strings.Split(strings.TrimRight(string(body), "\n"), "\n")
	if len(lines) != 1 {
		t.Errorf("expected 1 unique line, got %d: %v", len(lines), lines)
	}
}

func TestAddSortsAlphabetically(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "known-modules")
	for _, addr := range []string{"z/y/x", "a/b/c", "m/n/o"} {
		if err := Add(path, addr); err != nil {
			t.Fatalf("Add %s: %v", addr, err)
		}
