	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"a/b/c", "m/n/o", "z/y/x"}
	if len(got) != len(want) {
		t.Fatalf("got %d lines, want %d", len(got), len(want))
	}
	for i := range got {
		if got[i] != want[i] {
			t.Errorf("got[%d] = %s, want %s", i, got[i], want[i])
		}
	}
